function render(){const current=screen(state.page);root.innerHTML='<div class="rz-demo"><div><span class="rz-demo-tag">UX-прототип · учебные данные · '+registry.length+' экранов</span></div><div class="rz-demo-controls"><div class="rz-switch" aria-label="Кабинет"><button type="button" data-action="role:patient" aria-pressed="'+(!state.catalog&&state.role==='patient')+'">Пациент</button><button type="button" data-action="role:doctor" aria-pressed="'+(!state.catalog&&state.role==='doctor')+'">Врач</button><button type="button" data-action="catalog" aria-pressed="'+state.catalog+'">Все экраны</button></div><select aria-label="Клинический сценарий" data-control="patient">'+Object.entries(patients).map(([id,p])=>'<option value="'+id+'"'+(id===state.patient?' selected':'')+'>'+p.scenario+'</option>').join('')+'</select></div></div><div class="rz-app"><header class="rz-apphead"><div class="rz-brand"><div class="rz-mark">r</div><div><div class="rz-wordmark">razuma</div><div class="rz-product">Клинический компас</div></div></div><div class="rz-row"><span class="rz-head-patient rz-small">'+(state.role==='doctor'?'Врач · '+doctor:pt().name+' · '+pt().id)+'</span>'+btn(ic('bell')+' Уведомления','nav:'+(state.role==='doctor'?'D01':'P28'),'ghost')+btn(ic('user-round')+' Профиль','nav:'+(state.role==='doctor'?'D29':'P29'),'ghost')+'</div></header>'+(state.toast?'<div class="rz-toast" role="status">'+esc(state.toast)+'</div>':'')+(state.catalog?catalog():stateBar()+'<div class="rz-layout">'+sidebar()+'<main class="rz-main" aria-live="polite" aria-label="'+esc(current[1])+'">'+modal()+pages[state.page]()+'</main></div>'+bottomnav())+'<footer class="rz-screenfoot"><span>'+(state.catalog?'Карта экранов по актуальной версии проекта':current[0]+' · '+current[1]+' · раздел '+current[3])+'</span><div class="rz-row">'+btn('Назад','back','ghost')+btn('Карта экранов','catalog','ghost')+'</div></footer></div>';}
function sidebar(){const items=state.role==='patient'?[['P03','Сегодня','sun'],['P12','Дневник','notebook-pen'],['P23','План','calendar-check'],['P26','Связь','messages-square']]:[['D01','Задачи','list-checks'],['D02','Пациенты','users'],['D24','Сообщения','messages-square'],['D30','База знаний','book-open'],['D29','Наблюдение','settings-2']];return '<aside class="rz-sidebar"><div class="rz-side-label">'+(state.role==='patient'?'Моё наблюдение':'Кабинет врача')+'</div>'+items.map(([id,t,icon])=>'<button class="rz-nav '+(state.page===id?'active':'')+'" type="button" data-action="nav:'+id+'">'+ic(icon)+t+'</button>').join('')+'<div class="rz-side-label">Быстрый доступ</div>'+btn(state.role==='patient'?'Заполнить опрос':'Карточка пациента','nav:'+(state.role==='patient'?'P15':'D04'),'ghost')+btn(state.role==='patient'?'Нужна срочная помощь':'Срочное событие','nav:'+(state.role==='patient'?'P22':'D21'),'ghost')+'<div class="rz-side-person">'+badge('Учебная клиника')+'<p class="rz-muted" style="margin-top:9px">Ответ врача: '+scheduleLabel()+'</p><p class="rz-small" style="margin-top:8px">При непосредственной опасности не ждите ответа в приложении.</p></div></aside>';}
function bottomnav(){const a=state.role==='patient'?[['P03','Сегодня'],['P12','Дневник'],['P23','План'],['P26','Связь']]:[['D01','Задачи'],['D02','Пациенты'],['D24','Связь'],['D29','Режим']];return '<nav class="rz-bottomnav" aria-label="Основная навигация">'+a.map(([id,t])=>'<button type="button" class="'+(state.page===id?'active':'')+'" data-action="nav:'+id+'">'+t+'</button>').join('')+'</nav>';}
function catalog(){return '<div class="rz-catalog">'+top('Все экраны','Откройте любой экран или пройдите сценарий с начала.')+'<div class="rz-row">'+btn('Запись → результат → врач','flow:diary','primary')+btn('Опрос → уточнение безопасности','flow:safety')+btn('Проверка терапии → план','flow:therapy')+'</div>'+[['Пациент',P],['Врач',D],['Вход и права доступа',U]].map(([t,r])=>'<section class="rz-catalog-section"><h2>'+t+' <span class="rz-muted">· '+r.length+'</span></h2><div class="rz-catalog-grid">'+r.map(([id,title,sub,sec])=>'<button class="rz-screenlink cursor-interaction" type="button" data-action="nav:'+id+'"><span class="rz-screen-id">'+id+'</span><span>'+title+'<small>'+sub+'</small></span></button>').join('')+'</div></section>').join('')+'</div>';}
function go(id){if(!pages[id])throw new Error('Unknown screen '+id);stopRecord();state.history.push(state.page);state.page=id;state.catalog=false;state.modal=null;state.toast='';state.variant='default';if(id[0]==='P')state.role='patient';if(id[0]==='D')state.role='doctor';if(id==='P16')state.scale='PHQ';if(id==='P17')state.scale='GAD';state.qIndex=Math.min(state.qIndex,(state.scale==='PHQ'?9:7)-1);render();}
function toast(t){state.toast=t;render();}
function showModal(title,body,buttons=[]){state.modal={title,body,buttons};render();}
function stopRecord(){if(state.recordTimer){clearInterval(state.recordTimer);state.recordTimer=null;}state.recording=false;}
function setBind(path,value){const parts=path.split('.');let obj=state;while(parts.length>1)obj=obj[parts.shift()];obj[parts[0]]=value;}
const pages={};
pages.P01=()=>'<div class="rz-center">'+top('Вас пригласили в Razuma','Наблюдение между приёмами у вашего врача.')+panel('Учебная клиника',item(doctor,'Лечащий врач',badge('Приглашение активно'),'<div class="rz-avatar">ЕС</div>')+'<div class="rz-separator"></div>'+kv([['Пациент',pt().name+', '+ageLabel(pt().age)+' · '+pt().id],['Ответ врача',scheduleLabel()],['Что доступно','Дневник, опросники, план и переписка']])+note('Сервис не предполагает круглосуточного наблюдения. Инструкция по срочной помощи доступна всегда.','neutral'),actions(btn('Принять приглашение','nav:P02','primary'),btn('Это не мой врач','wrongdoctor','ghost')))+'</div>';
pages.P02=()=>top('Согласия и доступ','Вы выбираете, какие данные использовать.')+panel('Медицинское сопровождение',check('Согласие на обработку данных для сопровождения','form.consentCare',state.form.consentCare,'Обязательно для наблюдения в клинике. Доступ — у закреплённой команды врачей.')+check('Разрешаю использовать мои аудио- и видеозаписи для анализа','form.consentMedia',state.form.consentMedia,'Необязательно. Можно вести дневник только текстом.')+check('Разрешаю исследовательское использование данных','form.consentResearch',state.form.consentResearch,'Отдельное необязательное согласие. Отказ не влияет на помощь.')+note('Доступ к камере и микрофону запрашивается только при записи.','neutral'),actions(btn('Продолжить','acceptconsents','primary'),btn('Условия обработки','consentinfo','ghost')))+(state.form.errorConsent?'<p class="rz-error" role="alert">Для сопровождения нужно подтвердить первое согласие.</p>':'');
pages.P03=()=>top('Здравствуйте, '+pt().name,'Как вы сегодня себя чувствуете?',btn(ic('plus')+' Запись','nav:P04','primary'))+'<div class="rz-stack"><div class="rz-hero"><div><h2>'+ (state.entryAdded?'Сегодняшняя запись отправлена':'Одна короткая запись сегодня')+'</h2><p>'+(state.entryAdded?'Врач увидит её в вашей карточке.':'Настроение, сон и то, что важно сообщить врачу.')+'</p>'+actions(btn(state.entryAdded?'Открыть запись':'Отметить самочувствие','nav:'+(state.entryAdded?'P13':'P04'),'primary'))+'</div><div class="rz-hero-number">01</div></div>'+cols(panel('По плану',item('PHQ-9 и GAD-7','Сегодня · за последние 2 недели',btn('Заполнить','nav:P15','soft'))+item('Контрольный приём','31 октября · 11:00',btn('Мой план','nav:P23','ghost'))),panel('Связь с врачом','<p>'+doctor+'</p><p class="rz-small">'+scheduleLabel()+'</p>'+actions(btn('Написать','nav:P26'),btn('Попросить связаться','nav:P27','ghost'))))+panel('Последние дни',chart([5,6,4,5,6],['13 окт','14 окт','15 окт','16 окт','17 окт'],'Настроение по дневнику от 0 до 10')+'<small>Дневниковая оценка настроения, не диагностический балл.</small>',actions(btn('Вся динамика','nav:P14','ghost')))+note('При непосредственной опасности не ждите ответа в чате. '+btn('Срочная помощь','nav:P22','ghost'),'neutral')+'</div>';
pages.P04=()=>top('Короткая запись','Ваши ощущения за сегодня.')+steps(1,3)+panel('Самочувствие','<label class="rz-field"><span>Настроение <output id="rz-mood-value">'+state.form.mood+'</output> / 10</span><input type="range" min="0" max="10" step="1" value="'+state.form.mood+'" data-bind="form.mood" data-range="mood"><small>0 — очень плохое · 10 — очень хорошее</small></label><label class="rz-field"><span>Тревога <output id="rz-anxiety-value">'+state.form.anxiety+'</output> / 10</span><input type="range" min="0" max="10" value="'+state.form.anxiety+'" data-bind="form.anxiety" data-range="anxiety"><small>0 — нет тревоги · 10 — очень сильная</small></label>'+cols(field('Сколько часов спали?','form.sleep',state.form.sleep,'number','min="0" max="24" step="0.5"'),select('Обычные дела','form.activity',['Без трудностей','С некоторыми трудностями','С большими трудностями','Не могу выполнять'],state.form.activity))+area('Что важно рассказать врачу?','form.diaryText',state.form.diaryText,'Можно оставить пустым'),actions(btn('Далее: лечение','nav:P05','primary'),btn('Нужна срочная помощь','nav:P22','ghost')));
pages.P05=()=>top('Приём препаратов','Отметьте, как прошёл день.')+steps(2,3)+panel(state.planApproved[state.patient]&&state.approvedMeds[state.patient]==='avi'?'Авиандр · подтверждённый учебный план':'Лечение по плану врача',(state.planApproved[state.patient]&&state.approvedMeds[state.patient]==='avi'?'<p class="rz-muted">Назначение подтверждено врачом в этом макете.</p>':note('В выбранном сценарии лекарственное назначение ещё не утверждено. Отметка ниже демонстрирует ввод по уже действующему назначению.','neutral'))+'<div class="rz-options" style="margin-top:15px">'+['Принял','Пропустил','Не помню'].map(v=>'<button type="button" class="rz-option cursor-interaction" aria-pressed="'+(state.form.medStatus===v)+'" data-action="medstatus:'+v+'">'+ic(v==='Принял'?'circle-check':'circle')+v+'</button>').join('')+'</div>'+(state.form.medStatus==='Пропустил'?'<div style="margin-top:15px">'+select('Причина пропуска','form.medReason',['Не выбрано','Забыл(а)','Нежелательное явление','Не было препарата','Другая причина'],state.form.medReason)+'</div>':'')+'<div class="rz-separator"></div>'+btn('Появилась новая жалоба','nav:P25','ghost'),actions(btn('Сохранить и продолжить','savemed','primary'),btn('Пропустить этот шаг','nav:P06','ghost')));
pages.P06=()=>top('Как удобнее рассказать?','Запись необязательна. Можно ограничиться текстом.')+steps(3,3)+'<div class="rz-cols three">'+panel('Текст','<p class="rz-muted">Дополните короткую запись.</p>',actions(btn('Открыть текст','textentry','block')))+panel('Голосовое','<p class="rz-muted">30–60 секунд о самочувствии.</p>',actions(btn(ic('mic')+' Записать','recordtype:audio','block')))+panel('Видеокружочек','<p class="rz-muted">Привычный формат видеодневника.</p>',actions(btn(ic('video')+' Записать','recordtype:video','primary block')))+'</div>'+panel('Ваш текст',area('Комментарий врачу','form.diaryText',state.form.diaryText),actions(btn('Отправить без аудио и видео','submittext','primary')));
function recorder(video){const s=String(state.recordSeconds%60).padStart(2,'0');return top(video?'Видеокружочек':'Голосовая запись','Что изменилось с прошлой записи и что сегодня было труднее обычного?')+panel('',note('Демонстрация записи: камера и микрофон не включаются.','neutral')+'<div class="rz-record">'+(video?'<div class="rz-video" aria-label="Пример видеокружочка"><span class="rz-person">'+pt().initials+'</span></div>':wave())+'<div class="rz-clock">00:'+s+'</div><p class="rz-muted">'+(state.recording?'Идёт демонстрационная запись':'Тихое место'+(video?' и привычное освещение':'')+' помогут сравнению записей')+'</p>'+actions(state.recording?btn(ic('square')+' Остановить','stoprecord','primary'):btn(ic(video?'video':'mic')+' Начать демозапись','startrecord','primary'),btn('Отмена','nav:P06','ghost'))+'</div>'+btn('Камера или микрофон недоступны','nav:P30','ghost'));}
