pages.P09=()=>top('Проверьте запись','До отправки её можно удалить или записать заново.')+panel('',(state.mediaType==='video'?'<div class="rz-record"><div class="rz-video"><span class="rz-person">'+pt().initials+'</span></div></div>':'')+wave()+'<div class="rz-row">'+btn(ic(state.mediaPlaying?'pause':'play')+' '+(state.mediaPlaying?'Пауза':'Посмотреть пример'),'playmedia')+'<span class="rz-small">00:'+String(state.recordSeconds||42).padStart(2,'0')+' · учебный фрагмент</span></div>'+(state.mediaPlaying?note('В этом примере пациент рассказывает о сне, тревоге и концентрации. Реальные медиа не воспроизводятся.','neutral'):'')+area('Дополнение к записи','form.diaryText',state.form.diaryText),actions(btn('Отправить врачу','sendentry','primary'),btn('Записать заново','rerecord'),btn('Удалить','deletemedia','ghost')));
pages.P10=()=>top('Отправка записи','Статус виден на каждом этапе.')+panel('Ваша запись',(state.variant==='error'?note('Сервер не принял запись. Врач её пока не получил.','danger'):'')+['Записано на устройстве','Отправляется','Получено сервером','Анализируется','Доступно врачу'].map((t,i)=>'<div class="rz-status-dots"><span class="rz-dot '+(i<=state.uploadStage?'done':'')+'"></span><span>'+t+'</span>'+(i===state.uploadStage?badge('Сейчас'):'')+'</div>').join('')+note('При выявленном опасном признаке уведомление отправляется отдельно, без ожидания анализа записи.','neutral'),actions(state.variant==='error'?btn('Повторить отправку','retryupload','primary'):btn(state.uploadStage<4?'Следующий этап':'Открыть результат',state.uploadStage<4?'uploadnext':'nav:P11','primary'),btn('Показать сбой соединения','nav:P31','ghost')));
pages.P11=()=>top('Запись получена','Она доступна вашему врачу.')+panel('Что дальше',badge('Передано в карточку')+'<p style="margin-top:12px">Следующая короткая запись — завтра. Сегодня можно заполнить плановые опросники.</p>'+note('Врач отвечает в рабочее время: пн–пт, 09:00–18:00. Немедленный ответ не гарантируется.','neutral'),actions(btn('Вернуться на сегодня','nav:P03','primary'),btn('Опросники','nav:P15'),btn('Посмотреть со стороны врача','nav:D04','ghost')));
pages.P12=()=>top('Мой дневник','Записи помогают вспомнить, что менялось между приёмами.',btn('Добавить запись','nav:P04','primary'))+panel('Октябрь',item('Сегодня · настроение '+state.form.mood+'/10',state.entryAdded?'Запись доступна врачу':'Учебная запись · сон 7 часов',btn('Открыть','nav:P13'),badge(state.entryAdded?'Доставлено':'Пример'))+item('16 октября · настроение 5/10','Голосовое · 00:48 · врач просмотрел',btn('Открыть','nav:P13','ghost'))+item('15 октября · настроение 4/10','Текст · было трудно сосредоточиться',btn('Открыть','nav:P13','ghost'))+item('14 октября','Запись отсутствует',badge('Нет данных','neutral')),actions(btn('Динамика','nav:P14'),btn('Показать пустой дневник','nav:P32','ghost')));
pages.P13=()=>top('Запись за 17 октября','Видно, что доставлено, а что ещё ожидает ответа.')+panel('Моя запись',kv([['Настроение',state.form.mood+' / 10'],['Тревога',state.form.anxiety+' / 10'],['Сон',esc(state.form.sleep)+' ч'],['Обычные дела',esc(state.form.activity)],['Лечение',state.medTaken?esc(state.form.medStatus):'Нет подтверждённой отметки']])+'<div class="rz-source">'+esc(state.form.diaryText||'Без комментария')+'</div>'+(state.mediaReady?wave():'')+'<div style="margin-top:12px">'+badge(state.entryAdded?'Доступно врачу':'Учебный пример')+' '+badge('Ответ ожидается','neutral')+'</div>',actions(btn('Написать врачу','nav:P26'),btn('Моя динамика','nav:P14','ghost')));
pages.P14=()=>top('Динамика самочувствия','Ваши оценки и комментарии врача за 14 дней.')+cols(panel('Настроение · 0–10',chart([4,5,4,6,6],['3 окт','7 окт','10 окт','14 окт','17 окт'],'Настроение по дневнику')+'<small>Более высокое значение — лучшее настроение.</small>'),panel('Тревога · 0–10',chart([8,7,7,6,5],['3 окт','7 окт','10 окт','14 окт','17 окт'],'Тревога по дневнику')+'<small>Более высокое значение — сильнее тревога.</small>'))+panel('Комментарий врача','<p>Оцениваем изменения вместе со сном, обычными делами и лечением. Одна запись не определяет состояние.</p><p class="rz-small" style="margin-top:8px">'+doctor+' · 15 октября</p>',actions(btn('Подготовить отчёт','patientreport'),btn('История опросов','nav:P15','ghost')));
pages.P15=()=>top('Клинические опросники','Оцените самочувствие за последние 2 недели.')+panel('Запланировано на сегодня',item('PHQ-9','9 вопросов · симптомы депрессии',btn('Начать','startscale:PHQ','primary'))+item('GAD-7','7 вопросов · тревога',btn('Начать','startscale:GAD','primary')))+panel('Последние результаты',table(['Дата','Опросник','Баллы'],[['3 октября','PHQ-9',String(pt().phq)],['3 октября','GAD-7',String(pt().gad)]]),actions(btn('Что означают результаты','scaleinfo','ghost')))+note('Шкалы помогают оценке врача и не устанавливают диагноз.','neutral');
function questionnaire(kind){const a=kind==='PHQ'?PHQ:GAD,opts=kind==='PHQ'?optionsPHQ:optionsGAD;const i=state.qIndex;return top(kind==='PHQ'?'PHQ-9':'GAD-7','Как часто за последние 2 недели Вас беспокоили следующие проблемы?')+'<div class="rz-progress-caption"><span>Вопрос '+(i+1)+' из '+a.length+'</span><span>'+state.answers[kind].filter(v=>v!==null).length+' ответов</span></div>'+steps(i+1,a.length)+panel(a[i],'<div class="rz-options">'+opts.map((t,v)=>'<button class="rz-option cursor-interaction" type="button" aria-pressed="'+(state.answers[kind][i]===v)+'" data-action="answer:'+v+'">'+ic(state.answers[kind][i]===v?'circle-check':'circle')+'<span>'+t+'</span></button>').join('')+'</div>',actions(btn(i===a.length-1?'Завершить':'Далее','qnext','primary'),btn('Голосовой ответ','voicequestion'),btn('Назад','qprev','ghost',i===0),btn('Пропустить','qskip','ghost')))+source(kind==='PHQ'?'phq':'gad','версия опросника');}
pages.P16=()=>questionnaire('PHQ');pages.P17=()=>questionnaire('GAD');
pages.P18=()=>top('Подтвердите голосовой ответ','Выбранный вариант не сохранится без вашего подтверждения.')+panel('Распознанный ответ',wave()+note('Пример распознавания: «Несколько дней».','neutral')+select('Правильный вариант','form.voiceValue',state.scale==='PHQ'?optionsPHQ:optionsGAD,state.form.voiceValue),actions(btn('Подтвердить ответ','confirmvoice','primary'),btn('Повторить пример','repeatvoice'),btn('Вернуться к кнопкам','nav:'+state.voiceReturn,'ghost')));
pages.P19=()=>{const a=state.answers[state.scale],miss=a.map((v,i)=>v===null?i+1:null).filter(Boolean);return top('Есть пропущенные ответы','Суммарный балл пока не рассчитывается.')+panel('Незавершённый опрос',note('Не заполнены вопросы: '+(miss.join(', ')||'нет')+'.','warning')+'<p style="margin-top:12px">Можно вернуться к вопросам или сохранить незавершённую анкету.</p>',actions(btn('Вернуться к первому пропуску','missingquestion','primary'),btn('Сохранить и выйти','savedraftscale','ghost')));};
pages.P20=()=>{const r=state.lastScore||{kind:'PHQ',score:pt().phq};return top('Ответы сохранены','Результат доступен врачу.')+panel(r.kind==='PHQ'?'PHQ-9':'GAD-7','<div class="rz-metric">'+r.score+' <span>из '+(r.kind==='PHQ'?27:21)+'</span></div><p class="rz-muted" style="margin-top:8px">Результат опроса не является диагнозом. Врач оценит его вместе с другими данными.</p>'+(r.kind==='PHQ'?select('Насколько эти проблемы мешали работать, заниматься домашними делами или общаться?','form.functioning',['Совсем не трудно','Немного трудно','Очень трудно','Чрезвычайно трудно'],state.form.functioning||'Немного трудно'):'')+(state.safetyStatus==='no'?note('Дополнительно создана задача врачу для оценки безопасности сегодня.','warning'):''),actions(btn('На сегодня','nav:P03','primary'),btn('Написать врачу','nav:P26'),btn('Результат в кабинете врача','nav:D09','ghost')));};
pages.P21=()=>top('Уточним, нужна ли помощь сейчас','Ответ поможет выбрать следующий шаг.')+panel('Есть ли сейчас непосредственная опасность?','<p>Есть ли у вас намерение причинить себе вред, конкретный план или ощущение, что вы не можете оставаться в безопасности?</p><div class="rz-options" style="margin-top:17px">'+[['yes','Да, опасность есть'],['unsure','Не могу уверенно сказать'],['no','Нет непосредственной опасности']].map(([v,t])=>'<button class="rz-option cursor-interaction" type="button" data-action="safety:'+v+'">'+t+'</button>').join('')+'</div>'+note('При непосредственной опасности звоните 112 или 103. Не ждите ответа в приложении.','danger'));
pages.P22=()=>top('Срочная помощь','Не ждите ответа в приложении.')+panel('Если есть непосредственная опасность',note('Позвоните 112 или 103. Если можете, обратитесь за помощью к человеку рядом.','danger')+actions(btn('Позвонить 112','emergencycall:112','danger'),btn('Позвонить 103','emergencycall:103'),btn('Связаться с клиникой','nav:P27'))+'<div class="rz-separator"></div>'+kv([['Уведомление врачу',state.redAlert?'Создано в учебной карточке':'Доступно при выявленном опасном признаке'],['Режим клиники','Пн–пт, 09:00–18:00; не круглосуточно']])+note('Получение уведомления врачом не означает, что помощь уже оказана.','neutral'),actions(btn('Я уже получил(а) помощь','helpreceived','soft'),btn('Вернуться','nav:P03','ghost')));
pages.P23=()=>{const p=state.approvedPlans[state.patient],r=state.approvedReferrals[state.patient];return top('Мой план','Показаны только решения, подтверждённые врачом.')+panel('Наблюдение',item('Дневник самочувствия','Короткая запись 1 раз в день',btn('Заполнить','nav:P04','soft'))+item('PHQ-9 и GAD-7','Раз в 14 дней или по назначению',btn('Опросники','nav:P15','ghost'))+item('Контрольный приём',esc(p?p.visit:'31 октября, 11:00'),btn('Задать вопрос','nav:P26','ghost')))+(p?panel('Новый план утверждён',badge('Подтверждено врачом')+'<p style="margin-top:10px">'+esc(p.comment)+'</p>'+(p.med==='avi'?item('Авиандр','20 мг дважды в сутки · учебное назначение',btn('Подробнее','nav:P24')):p.med==='manual'?item(esc(p.manualRx),'Индивидуальное решение врача'+(p.offlabel?' · вне зарегистрированной инструкции':''),btn('Задать вопрос','nav:P26')):note('Лекарственное назначение не добавлено.','neutral'))):panel('Лекарственные назначения',note('Новых подтверждённых назначений нет. Предложения системы здесь не отображаются.','neutral')))+(r?panel('Направление к психиатру',badge('Подтверждено врачом')+kv([['Необходимость',r.need],['Срок',r.urgency],['Основание',esc(r.reason)]])):'');};
pages.P24=()=>top('Назначение врача','Учебный пример подтверждённой карточки.')+panel('Авиандр',state.planApproved[state.patient]&&state.approvedMeds[state.patient]==='avi'?badge('Подтверждено '+doctor):badge('Пример экрана · назначения ещё нет','warning'))+panel('Как принимать',kv([['Разовая доза','20 мг'],['Режим','Дважды в сутки, за 30 минут до еды'],['Продолжительность','По утверждённому плану врача']])+note('Эта карточка показывает интерфейс назначения для вымышленного пациента. Она не является назначением для пользователя макета.','neutral'),actions(btn('Отметить приём','nav:P05','primary'),btn('Сообщить о жалобе','nav:P25')))+panel('Если появились новые симптомы','<p>Сообщите врачу о сонливости, головокружении или других новых жалобах. При непосредственной опасности используйте раздел срочной помощи.</p>',actions(btn('Написать врачу','nav:P26'),btn('Срочная помощь','nav:P22','ghost')));
pages.P25=()=>top('Новая жалоба','Важно сообщить, когда она появилась и как мешает.')+panel('Что изменилось',select('Жалоба','form.sideEffect',['Сонливость','Головокружение','Слабость','Другая жалоба','Затруднённое дыхание / отёк лица','Сообщение о передозировке'],state.form.sideEffect)+cols(select('Когда началось','form.sideWhen',['Сегодня','Вчера','После начала лечения','После изменения дозы'],state.form.sideWhen),select('Влияние на обычные дела','form.sideSeverity',['Почти не мешает','Мешает обычным делам','Не могу выполнять обычные дела'],state.form.sideSeverity))+area('Что ещё важно врачу','form.sideComment',state.form.sideComment,'Принимаемые средства, время появления симптома'),actions(btn('Передать врачу','savesideeffect','primary'),btn('Нужна срочная помощь','nav:P22','ghost')))+(state.sideEffectSaved?note('Жалоба сохранена. Оценка причины и изменение лечения — решение врача.'):'' );
function chatBody(role){return '<div class="rz-chat">'+state.chat.map(m=>'<div class="rz-message '+(m.who===role?'mine':'')+'">'+esc(m.text)+'<small>'+(m.who==='doctor'?doctor:pt().name)+' · '+m.time+' · доставлено</small></div>').join('')+'</div>'+area('Сообщение','form.message',state.form.message,'Напишите сообщение')+actions(btn('Отправить','sendchat','primary'));}
pages.P26=()=>top('Связь с врачом',doctor+' · ответ в рабочее время')+note('Сегодня выходной. При непосредственной опасности не ждите ответа в переписке.','warning')+panel('',chatBody('patient'))+actions(btn('Попросить связаться','nav:P27'),btn('Срочная помощь','nav:P22','ghost'));
pages.P27=()=>top('Попросить врача связаться','Запрос появится в очереди задач клиники.')+panel('Ваш запрос',select('Причина','form.contactReason',['Хочу обсудить самочувствие','Новая жалоба на фоне лечения','Вопрос о назначении','Не понимаю план наблюдения'],state.form.contactReason)+select('Когда удобно','form.contactTime',['В рабочее время','В первой половине дня','Во второй половине дня'],state.form.contactTime)+note('Для немедленной помощи звоните 112 или 103. Запрос обратной связи не заменяет экстренное обращение.','neutral'),actions(btn(state.requestSent?'Запрос отправлен':'Отправить запрос','contactrequest','primary',state.requestSent),btn('Вернуться к сообщениям','nav:P26','ghost')));
pages.P28=()=>top('Уведомления','Только информация о вашем наблюдении.',btn('Отметить прочитанными','readnotifications','ghost'))+panel('',item('Пора заполнить опросники','Сегодня · PHQ-9 и GAD-7',btn('Открыть','nav:P15','soft'))+item(state.planApproved[state.patient]?'Врач подтвердил новый план':'План наблюдения доступен','Все назначения находятся в разделе «План»',btn('Открыть','nav:P23','ghost'))+item('Сообщение от врача','Откройте защищённую переписку',btn('Прочитать','nav:P26','ghost')))+(state.notificationsRead?note('Все уведомления прочитаны.'):'' );
