pages.P31=()=>top('Нет соединения','Запись не доставлена врачу.')+panel('',empty('Отправку можно повторить','Приложение не будет показывать, что врач получил запись, пока сервер её не принял.',[btn('Повторить отправку','retryupload','primary'),btn('Вернуться к записи','nav:P09')],'wifi-off')+note('При непосредственной опасности звоните 112 или 103. Контакты доступны независимо от отправки записи.','danger'),actions(btn('Срочная помощь','nav:P22','ghost')));
pages.P32=()=>top('Мой дневник','Здесь появится история ваших записей.')+panel('',empty('Начнём с одной короткой записи','Можно отметить настроение и сон или добавить голосовое сообщение. Камера необязательна.',[btn('Первая запись','nav:P04','primary')],'notebook-pen'));
function risk(){if(state.patient==='C')return'excluded';if(state.form.egfr===''||state.form.egfr==null)return'unknown';if(Number(state.form.egfr)<60||state.form.maoi==='Да'||state.form.liver==='Есть нарушение')return'contra';return'eligible';}
function riskNote(){const r=risk();return r==='excluded'?note('Не подходит для лечения депрессии как самостоятельного заболевания: такого зарегистрированного показания в карточке нет.','danger'):r==='contra'?note('Вариант исключён системой: выявлено противопоказание. Подтверждение плана с этим препаратом заблокировано.','danger'):r==='unknown'?note('Недостаточно данных для лекарственной рекомендации. Уточните функцию почек и другие обязательные сведения.','warning'):note('По учебным данным противопоказаний не выявлено. Назначение возможно только после проверки и решения врача.');}
pages.D01=()=>top('Задачи на сегодня','Сначала то, что требует внимания врача.',btn('Пригласить пациента','nav:D03','primary'))+'<div class="rz-chiprow">'+['Все','Срочные','Новые жалобы','Пропуски','Проверить данные'].map(t=>'<button class="rz-chip cursor-interaction" type="button" data-action="taskfilter:'+t+'" aria-pressed="'+((state.taskFilter||'Все')===t)+'">'+t+'</button>').join('')+'</div>'+panel('Очередь задач',((!state.taskFilter||['Все','Срочные'].includes(state.taskFilter))?item((state.redAlert?'Непосредственная опасность':'Оценить безопасность сегодня'),pt().id+' · '+(state.alertResolved?'Закрыто врачом':state.doctorAck?'Принято врачом':'Ожидает подтверждения'),btn('Открыть','nav:D21',state.redAlert?'danger':'soft'),badge(state.redAlert?'Сейчас':'Сегодня',state.redAlert?'danger':'warning')):'')+((!state.taskFilter||['Все','Новые жалобы'].includes(state.taskFilter))?item('Новая жалоба: '+state.form.sideEffect,pt().id+' · проверить связь с лечением',btn('Оценить','nav:D20'),badge('Новая','warning')):'')+((!state.taskFilter||['Все','Проверить данные'].includes(state.taskFilter))?item(state.entryAdded?'Новая запись пациента':'Проверить извлечённый анамнез',pt().id+' · '+(state.entryAdded?'аудио / видео / самоотчёт':'есть противоречие в назначениях'),btn('Проверить','nav:'+(state.entryAdded?'D11':'D08')),badge('Проверка','neutral')):'')+((state.taskFilter==='Пропуски')?item('Проверить отметки о приёме',pt().id+' · 1 пропуск и 2 неизвестных значения',btn('Открыть','nav:D19')):''))+cols(panel('Режим наблюдения','<p>Основной врач: '+doctor+'</p><p class="rz-small">Экстренная инструкция пациенту доступна всегда.</p>',actions(btn('Часы и резервный врач','nav:D29','ghost'))),panel('Выбранный пациент',item(pt().name+', '+ageLabel(pt().age),pt().id,btn('Карточка','nav:D04'),'<div class="rz-avatar">'+pt().initials+'</div>')));
pages.D02=()=>top('Пациенты','Карточки, доступные вам как лечащему врачу.',btn('Пригласить','nav:D03','primary'))+panel('',table(['Пациент','Состояние наблюдения','Действие'],Object.entries(patients).map(([id,p])=>['<strong>'+p.name+'</strong><br><small>'+p.id+' · '+ageLabel(p.age)+'</small>',p.scenario+'<br>'+badge(id==='C'?'Психиатр обязателен':'Плановое наблюдение',id==='C'?'warning':'neutral'),btn('Открыть','patient:'+id)])))+actions(btn('Проверить запрет доступа к чужой карточке','nav:U04','ghost'));
pages.D03=()=>top('Пригласить пациента','Связь появится после принятия приглашения.')+panel('Данные приглашения',field('Имя или внутренний код пациента','form.newCode',state.form.newCode||pt().id)+kv([['Лечащий врач',doctor],['Клиника','Учебная клиника'],['Режим ответа','Пн–пт, 09:00–18:00']])+note('В приглашении нет диагноза или сведений о лечении.','neutral'),actions(btn('Создать приглашение','createinvite','primary'),btn('Посмотреть со стороны пациента','nav:P01','ghost')));
